import tempfile
import os

import streamlit as st
import numpy as np
from PIL import Image, ImageOps
import tensorflow as tf

# ------------------------------------------------------------------
# Grundeinstellungen der Seite
# ------------------------------------------------------------------
st.set_page_config(
    page_title="Fundstück-Scanner",
    page_icon="🔎",
    layout="centered",
    initial_sidebar_state="collapsed",
)

# ------------------------------------------------------------------
# Style (eigenes, ruhiges Design statt Standard-Streamlit-Look)
