# ------------------------------------------------------------------
# Kopfbereich
# ------------------------------------------------------------------
st.markdown('<div class="app-title">Fundstück-Scanner</div>', unsafe_allow_html=True)
st.markdown(
    '<div class="app-subtitle">Foto hochladen und automatisch erkennen lassen, '
    'um welche Kategorie es sich handelt.</div>',
    unsafe_allow_html=True,
)

# ------------------------------------------------------------------
# Kategorien (fest im Code hinterlegt)
# ------------------------------------------------------------------
LABELS = ['Kleidungsstücke', 'Schulsachen', 'Trinkflasche', 'Brotdose', 'Regenschirm', 'Schlüssel', 'Kopfhörer', 'Powerbank/Ladekabel', 'Brille', 'Geldtasche', 'Taschenrechner']

# ------------------------------------------------------------------
# Modell: als Base64-Text fest im Code hinterlegt, damit auf GitHub
# nur diese eine app.py-Datei benötigt wird.
# ------------------------------------------------------------------
MODEL_B64 = ""


@st.cache_resource
def load_model():
    model_bytes = base64.b64decode(MODEL_B64)
    with tempfile.NamedTemporaryFile(suffix=".h5", delete=False) as tmp:
        tmp.write(model_bytes)
        tmp_path = tmp.name
    try:
        model = tf.keras.models.load_model(tmp_path, compile=False)
    finally:
        os.remove(tmp_path)
    return model


def get_input_size(model):
    """Liest die vom Modell erwartete Bildgröße aus, mit sicherem Fallback."""
    try:
        shape = model.input_shape
        if isinstance(shape, list):
            shape = shape[0]
        _, h, w, _ = shape
        if h and w:
            return int(h), int(w)
    except Exception:
        pass
    return 224, 224


def prepare_image(image: Image.Image, size):
    image = ImageOps.exif_transpose(image)
    image = image.convert("RGB")
    image = ImageOps.fit(image, size, Image.Resampling.LANCZOS)
    array = np.asarray(image, dtype=np.float32)
    normalized = (array / 127.5) - 1.0
    return np.expand_dims(normalized, axis=0)


try:
    model = load_model()
    labels = LABELS
    model_ready = True
except Exception as e:
    model_ready = False
    st.error("Das Modell konnte nicht geladen werden.")
    st.exception(e)

# ------------------------------------------------------------------
# Bild-Upload und Erkennung
# ------------------------------------------------------------------
if model_ready:
    uploaded_file = st.file_uploader(
        "Foto auswählen",
        type=["jpg", "jpeg", "png", "webp"],
        label_visibility="collapsed",
    )

    if uploaded_file is not None:
        image = Image.open(uploaded_file)
        st.image(image, use_container_width=True)

        with st.spinner("Bild wird analysiert …"):
            input_size = get_input_size(model)
            batch = prepare_image(image, input_size)
            predictions = model.predict(batch, verbose=0)[0]

        order = np.argsort(predictions)[::-1]
        top_index = order[0]
        top_label = (
            labels[top_index] if top_index < len(labels) else f"Klasse {top_index}"
        )
        top_confidence = float(predictions[top_index]) * 100

        st.markdown(
            f"""
            <div class="result-card">
                <div class="result-label">Erkannt als</div>
                <div class="result-value">{top_label}</div>
                <div class="result-confidence">{top_confidence:.1f} % Übereinstimmung</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

        st.markdown('<div class="section-heading">Alle Kategorien</div>', unsafe_allow_html=True)

        rows = ""
        for idx in order:
            name = labels[idx] if idx < len(labels) else f"Klasse {idx}"
            pct = float(predictions[idx]) * 100
            rows += f"""
            <div class="bar-row">
                <div class="bar-name">{name}</div>
                <div class="bar-track">
                    <div class="bar-fill" style="width:{pct:.1f}%;"></div>
                </div>
                <div class="bar-pct">{pct:.1f} %</div>
            </div>
            """
        st.markdown(rows, unsafe_allow_html=True)
    else:
        st.caption("Es wird noch kein Foto ausgewertet – bitte oben eines hochladen.")
